SELECT

FROM product p
LEFT JOIN category c ON p.category_id = c.id
WHERE 1=1


    AND (
        p.category_id = #{categoryId}
        OR p.category_id IN (SELECT id FROM category WHERE parent_id = #{categoryId})
    )


    AND p.status = #{status}


    AND p.status = 1 AND c.status = 1

ORDER BY p.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM product p
LEFT JOIN category c ON p.category_id = c.id
WHERE 1=1


    AND (
        p.category_id = #{categoryId}
        OR p.category_id IN (SELECT id FROM category WHERE parent_id = #{categoryId})
    )


    AND p.status = #{status}


    AND p.status = 1 AND c.status = 1

mapper.update:
UPDATE product
name = #{name}, barcode = #{barcode}, category_id = #{categoryId}, specification = #{specification}, unit = #{unit}, purchase_price = #{purchasePrice}, selling_price = #{sellingPrice}, quantity = #{quantity}, min_stock = #{minStock}, description = #{description}, status = #{status}, update_time = #{updateTime}
WHERE id = #{id}

UPDATE product
SET quantity = #{quantity}
WHERE id = #{id}

UPDATE product p
SET p.quantity = (
    SELECT COALESCE(SUM(s.quantity), 0) FROM product_sku s WHERE s.product_id = #{productId} AND s.status = 1
),
p.update_time = NOW()
WHERE p.id = #{productId}

mapper.select:
SELECT p.id, p.name, p.barcode, c.name as category_name, p.specification, p.unit, p.quantity as quantity, p.min_stock, p.purchase_price, p.selling_price, (p.quantity * p.purchase_price) as inventory_value FROM product p LEFT JOIN category c ON p.category_id = c.id WHERE 1=1
AND p.category_id = #{categoryId}
AND p.status = #{status}
ORDER BY p.category_id, p.name

SELECT p.id, p.name, p.barcode, c.name as category_name, p.specification, p.unit, p.quantity, p.min_stock, p.purchase_price, p.selling_price FROM product p LEFT JOIN category c ON p.category_id = c.id WHERE p.quantity <= p.min_stock
AND p.category_id = #{categoryId}
AND p.status = #{status}
ORDER BY p.quantity DESC
